class Solution {
public:
    set<int> seen;
    bool find(TreeNode* node, int k) {
        if (!node) return false;
        if (seen.count(k - node->val)) return true;
        seen.insert(node->val);
        return find(node->left, k) || find(node->right, k);
    }
    bool findTarget(TreeNode* root, int k) {
        return find(root, k);
    }
};
